package tw.com.tft.documentscanner;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.*;import androidx.core.content.ContextCompat;import com.google.android.material.button.MaterialButtonToggleGroup;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import tw.com.tft.documentscanner.export.*;import tw.com.tft.documentscanner.imaging.*;import tw.com.tft.documentscanner.model.*;import tw.com.tft.documentscanner.session.ScanSessionStore;import tw.com.tft.documentscanner.util.*;import tw.com.tft.documentscanner.view.ZoomableImageView;public class PreviewActivity extends AppCompatActivity{private final ExecutorService w=Executors.newSingleThreadExecutor();private final AtomicInteger gen=new AtomicInteger();private ScanSessionStore store;private ZoomableImageView z;private ProgressBar pb;private TextView page;private MaterialButtonToggleGroup fg;private Bitmap shown;private Runnable pending;private final ActivityResultLauncher<String> perm=registerForActivityResult(new ActivityResultContracts.RequestPermission(),g->{if(g&&pending!=null){Runnable r=pending;pending=null;r.run();}});protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_preview);UiUtils.applyInsets(this,findViewById(R.id.rootPreview),false);store=ScanSessionStore.get(this);if(store.session().items.isEmpty()){finish();return;}z=findViewById(R.id.zoomView);pb=findViewById(R.id.progressPreview);page=findViewById(R.id.txtPreviewPage);fg=findViewById(R.id.filterGroup);findViewById(R.id.btnBackPreview).setOnClickListener(v->finish());findViewById(R.id.btnHomePreview).setOnClickListener(v->home());findViewById(R.id.btnResetZoom).setOnClickListener(v->z.resetZoom());findViewById(R.id.btnPrevPage).setOnClickListener(v->change(-1));findViewById(R.id.btnNextPage).setOnClickListener(v->change(1));findViewById(R.id.btnSaveOne).setOnClickListener(v->storage(()->save(false)));findViewById(R.id.btnSaveAll).setOnClickListener(v->storage(()->save(true)));findViewById(R.id.btnShareOne).setOnClickListener(v->share(false));findViewById(R.id.btnShareAll).setOnClickListener(v->share(true));fg.addOnButtonCheckedListener((g,id,c)->{if(!c)return;ScanItem i=store.session().current();FilterMode m=id==R.id.filterOriginal?FilterMode.ORIGINAL:id==R.id.filterSoft?FilterMode.SOFT_WHITE:id==R.id.filterBw?FilterMode.BLACK_WHITE:FilterMode.CLEAR;if(i.filter!=m){i.filter=m;store.persist(this);render();}});render();}private void render(){int n=gen.incrementAndGet();ScanItem i=store.session().current();page.setText((store.session().currentIndex+1)+" / "+store.session().items.size());int id=i.filter==FilterMode.ORIGINAL?R.id.filterOriginal:i.filter==FilterMode.SOFT_WHITE?R.id.filterSoft:i.filter==FilterMode.BLACK_WHITE?R.id.filterBw:R.id.filterClear;if(fg.getCheckedButtonId()!=id)fg.check(id);pb.setVisibility(View.VISIBLE);w.submit(()->{try{Bitmap s=ImageLoader.loadPreview(i.sourcePath,DeviceProfile.previewMaxSide(this));Bitmap o=ScannerApp.isOpenCvReady()?ImageProcessor.processPreview(s,i.corners,i.filter):FallbackProcessor.processPreview(s,i.corners,i.filter);s.recycle();runOnUiThread(()->{if(n!=gen.get()){o.recycle();return;}if(shown!=null&&!shown.isRecycled())shown.recycle();shown=o;z.setImageBitmap(o);pb.setVisibility(View.GONE);});}catch(Throwable e){runOnUiThread(()->pb.setVisibility(View.GONE));}});}private void change(int d){int x=store.session().currentIndex+d;if(x<0||x>=store.session().items.size())return;store.session().currentIndex=x;store.persist(this);render();}private void save(boolean all){pb.setVisibility(View.VISIBLE);w.submit(()->{try{if(all)ExportManager.saveAll(this,new ArrayList<>(store.session().items));else ExportManager.saveToPictures(this,store.session().current(),store.session().currentIndex+1);runOnUiThread(()->{pb.setVisibility(View.GONE);Toast.makeText(this,"已儲存到 Pictures/文件掃描與裁切",Toast.LENGTH_LONG).show();});}catch(Throwable e){runOnUiThread(()->pb.setVisibility(View.GONE));}});}private void share(boolean all){pb.setVisibility(View.VISIBLE);w.submit(()->{try{List<File>f=new ArrayList<>();if(all)for(int i=0;i<store.session().items.size();i++)f.add(ExportManager.renderToCache(this,store.session().items.get(i),i+1,"scan_share"));else f.add(ExportManager.renderToCache(this,store.session().current(),store.session().currentIndex+1,"scan_share"));ArrayList<android.net.Uri>u=ShareManager.filesToUris(this,f);runOnUiThread(()->{pb.setVisibility(View.GONE);ShareManager.share(this,u);});}catch(Throwable e){runOnUiThread(()->pb.setVisibility(View.GONE));}});}private void storage(Runnable r){if(Build.VERSION.SDK_INT>=29||ContextCompat.checkSelfPermission(this,Manifest.permission.WRITE_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED)r.run();else{pending=r;perm.launch(Manifest.permission.WRITE_EXTERNAL_STORAGE);}}private void home(){new AlertDialog.Builder(this).setTitle("是否確定離開？").setPositiveButton("回首頁",(d,x)->{store.clear(this);Intent i=new Intent(this,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);finishAffinity();}).setNegativeButton("取消",null).show();}public void onBackPressed(){finish();}protected void onDestroy(){super.onDestroy();gen.incrementAndGet();w.shutdownNow();if(shown!=null&&!shown.isRecycled())shown.recycle();}}